export const modules = [
 {id:'w1',chapter:'w',index:'01',title:'Was ist eine Willenserklärung?',icon:'sparkles',diagram:'signal',story:'Mira beginnt ihre Ausbildung bei der Werkstatt ReRide. Sie entdeckt ein gebrauchtes E-Bike und überlegt, ob sie es für ein Schulprojekt kaufen möchte.',intro:'Nicht jede Äußerung ist eine rechtlich wirksame Erklärung. Entscheidend ist der Wille, eine Rechtsfolge herbeizuführen.',theory:[
  {title:'Willenserklärung',body:'Eine **Willenserklärung** ist eine **Äußerung des Willens**, die auf die **Herbeiführung einer Rechtsfolge** gerichtet ist. Sie kann beispielsweise zu einem Vertragsschluss, einer Kündigung oder einem Testament beitragen.'},
  {title:'Wunsch oder rechtsgeschäftlicher Wille?',body:'„Das Fahrrad sieht gut aus“ ist grundsätzlich eine bloße Meinungsäußerung. „Ich kaufe dieses Fahrrad für 350 €“ kann dagegen – abhängig vom Zusammenhang – eine auf einen Vertragsschluss gerichtete Erklärung sein.'},
  {title:'Rechtsfolge',body:'Eine **Rechtsfolge** ist die Wirkung, die das Recht an eine Handlung knüpft, etwa die Entstehung von **Ansprüchen und Pflichten** aus einem Vertrag.'}],takeaway:'Fragen Sie zuerst: Soll diese Äußerung eine rechtliche Wirkung herbeiführen?'},
 {id:'w2',chapter:'w',index:'02',title:'Ausdrücklich oder schlüssig?',icon:'hand',diagram:'expression',story:'Mira schreibt der Verkäuferin eine Nachricht. In der Werkstatt legt ein Kunde wortlos einen Fahrradschlauch auf den Verkaufstresen.',intro:'Willenserklärungen müssen nicht immer ausgesprochen werden. Oft reicht ein Verhalten, das eindeutig auf einen entsprechenden Willen schließen lässt.',theory:[
  {title:'Ausdrückliche Willenserklärung',body:'Eine **ausdrückliche Erklärung** vermittelt den Willen **unmittelbar durch Worte oder Zeichen**, zum Beispiel **mündlich**, **schriftlich** oder **elektronisch**.'},
  {title:'Konkludentes Handeln',body:'Bei **konkludentem (schlüssigem) Handeln** ergibt sich der rechtsgeschäftliche Wille **aus dem Verhalten**. Beispiele: Ware auf das Kassenband legen, per Handzeichen bei einer Versteigerung mitbieten oder am Automaten ein Ticket lösen.'},
  {title:'Kontext beachten',body:'Dasselbe Verhalten kann unterschiedliche Bedeutungen haben: Das bloße Berühren einer Ware begründet noch keinen Kaufvertrag. Der konkrete Kontext entscheidet darüber, wie ein Verhalten objektiv zu verstehen ist.'}],takeaway:'Ausdrücklich = Worte/Zeichen. Konkludent = verständliches Handeln.'},
 {id:'w3',chapter:'w',index:'03',title:'Schweigen und Zugang',icon:'mail-check',diagram:'access',story:'Mira erhält eine Nachricht mit einem abweichenden Preis. Außerdem fragt sie sich, ab wann eine Kündigung überhaupt wirkt.',intro:'Schweigen ist im Regelfall keine Zustimmung. Bei empfangsbedürftigen Erklärungen kommt es zusätzlich auf den Zugang an.',theory:[
  {title:'Schweigen',body:'**Bloßes Schweigen** hat grundsätzlich **keinen Erklärungswert**. Es bedeutet weder automatisch Annahme noch zwingend Ablehnung. Gesetzlich oder aufgrund besonderer Umstände können Ausnahmen gelten, etwa nach **§ 362 HGB** in seinem engen Anwendungsbereich.'},
  {title:'Zugang',body:'Eine **empfangsbedürftige Willenserklärung** wird gegenüber einer abwesenden Person grundsätzlich wirksam, wenn sie in deren **Machtbereich gelangt** und unter normalen Umständen mit einer **Kenntnisnahme zu rechnen** ist (§ 130 BGB). Tatsächliches Lesen ist nicht immer erforderlich.'},
  {title:'Ausnahme nicht verallgemeinern',body:'Eine langjährige Geschäftsbeziehung allein macht Schweigen nicht automatisch zur Zustimmung. Auch ein bloßes „Ich schweige“ ist regelmäßig noch keine positive Annahmeerklärung.'}],takeaway:'Schweigen ist grundsätzlich neutral. Zugang heißt: Möglichkeit der Kenntnisnahme unter gewöhnlichen Umständen.'},
 {id:'r1',chapter:'r',index:'04',title:'Einseitige Rechtsgeschäfte',icon:'user-round',diagram:'unilateral',story:'In der Werkstatt wird ein Arbeitsverhältnis gekündigt. Mira erfährt außerdem, dass eine Kundin per Aushang Finderlohn ausgesetzt hat.',intro:'Einseitige Rechtsgeschäfte beruhen auf der Willenserklärung nur einer Seite. Nicht alle müssen jemand anderem zugehen.',theory:[
  {title:'Einseitiges Rechtsgeschäft',body:'Ein **einseitiges Rechtsgeschäft** erfordert für sein Zustandekommen **nur eine Willenserklärung**. Das heißt nicht, dass nur eine Person betroffen ist.'},
  {title:'Empfangsbedürftig',body:'**Empfangsbedürftige** Erklärungen müssen dem jeweiligen **Empfänger zugehen**, um wirksam zu werden. Typische Beispiele sind **Kündigung, Rücktritt und Anfechtung** (jeweils weitere Voraussetzungen möglich).'},
  {title:'Nicht empfangsbedürftig',body:'**Nicht empfangsbedürftige** Erklärungen müssen niemandem zugehen. Beispiele: **eigenhändiges Testament** und **Auslobung**. Sie haben jeweils eigene Wirksamkeitsvoraussetzungen; eine Auslobung wird etwa durch öffentliche Bekanntmachung wirksam.'}],takeaway:'Nur eine Willenserklärung nötig – mit oder ohne Zugangserfordernis.'},
 {id:'r2',chapter:'r',index:'05',title:'Verträge und Verpflichtungen',icon:'handshake',diagram:'obligations',story:'ReRide kauft Ersatzteile und erhält eine unentgeltliche Spende. Weshalb sind die Pflichten verschieden?',intro:'Ein Vertrag besteht aus mindestens zwei übereinstimmenden Willenserklärungen. Die daraus folgenden Pflichten können auf einer oder auf beiden Seiten liegen.',theory:[
  {title:'Vertrag',body:'Ein **Vertrag** ist ein **zwei- oder mehrseitiges Rechtsgeschäft**, das durch **übereinstimmende Willenserklärungen** zustande kommt (im Grundmodell: **Antrag und Annahme**).'},
  {title:'Einseitig verpflichtender Vertrag',body:'Bei einem **einseitig verpflichtenden Vertrag** wird grundsätzlich **nur eine Vertragspartei** zur Hauptleistung verpflichtet. Ein typisches Beispiel ist eine **unentgeltliche Schenkung**; die Annahme durch die andere Partei bleibt nötig.'},
  {title:'Zweiseitig verpflichtender Vertrag',body:'Bei einem **zweiseitig verpflichtenden Vertrag** entstehen **Leistungspflichten für beide Seiten**. Beim Kaufvertrag: Ware übereignen/übergeben ↔ Kaufpreis zahlen und Ware abnehmen (§ 433 BGB).'}],takeaway:'Einseitig/zweiseitig beim Entstehen ≠ einseitig/zweiseitig bei den Verpflichtungen.'},
 {id:'r3',chapter:'r',index:'06',title:'Antrag, Annahme und Vertrag',icon:'arrow-left-right',diagram:'contract',story:'Eine Verkäuferin schreibt: „350 € für das E-Bike, Abholung am Freitag.“ Mira antwortet: „Einverstanden!“ Später soll das Rad doch 390 € kosten.',intro:'Für einen Vertrag müssen Antrag und Annahme inhaltlich übereinstimmen. Eine veränderte Antwort ist im Regelfall keine Annahme, sondern ein neuer Antrag.',theory:[
  {title:'Antrag (Angebot)',body:'Ein **Antrag** ist eine **empfangsbedürftige Willenserklärung**, die so bestimmt ist, dass die andere Seite den Vertrag durch **einfaches Ja** zustande bringen kann.'},
  {title:'Annahme',body:'Die **Annahme** ist das **vorbehaltlose Einverständnis** mit dem Antrag. **Veränderungen** etwa beim Preis gelten regelmäßig als **Ablehnung verbunden mit einem neuen Antrag** (§ 150 Abs. 2 BGB).'},
  {title:'Vorbehalt / unverbindliche Werbung',body:'Eine allgemeine Verkaufsanzeige ist häufig nur eine **Einladung zur Abgabe eines Antrags** (invitatio ad offerendum). Eindeutige, individualisierte Nachrichten können dagegen bereits verbindliche Anträge sein. Der Einzelfall zählt.'}],takeaway:'Antrag + inhaltlich passende Annahme = Vertrag, sofern keine weiteren Hindernisse bestehen.'},
 {id:'f1',chapter:'f',index:'07',title:'Formfreiheit und Funktionen',icon:'file-check-2',diagram:'form',story:'ReRide kauft ein gebrauchtes Fahrrad per Handschlag. Als die Werkstatt eine weitere Halle mieten will, wird die Frage nach Formvorschriften wichtig.',intro:'Grundsätzlich ist ein Rechtsgeschäft formfrei. Manche Geschäfte müssen jedoch gesetzlich festgelegte Anforderungen erfüllen.',theory:[
  {title:'Formfreiheit',body:'Der Grundsatz der **Formfreiheit** bedeutet: Rechtsgeschäfte können in der Regel **mündlich, schriftlich, elektronisch oder schlüssig** abgeschlossen werden. Bei besonderen Rechtsgeschäften schreibt das Gesetz eine Form vor.'},
  {title:'Warnfunktion',body:'Die **Warnfunktion** schützt vor **unüberlegten Erklärungen** und macht die **Tragweite** eines Rechtsgeschäfts sichtbar, etwa beim Grundstückskauf.'},
  {title:'Beweisfunktion',body:'Die **Beweisfunktion** dient dazu, **Inhalt und Abgabe** einer Erklärung später nachweisen zu können. Sie hilft, Streit über Absprachen zu vermeiden.'},
  {title:'Textform zusätzlich beachten',body:'Die **Textform** (§ 126b BGB) erfordert eine **lesbare Erklärung auf einem dauerhaften Datenträger**, die den Erklärenden erkennen lässt. Eine handschriftliche Unterschrift ist nicht erforderlich. **Schriftform** (§ 126 BGB) ist grundsätzlich strenger.'}],takeaway:'Erst prüfen: formfrei oder Ausnahme? Dann die genaue gesetzliche Form bestimmen.'},
 {id:'f2',chapter:'f',index:'08',title:'Die Formstufen',icon:'stamp',diagram:'levels',story:'Die Werkstatt verhandelt über den Kauf einer kleinen Immobilie. Für den Kaufvertrag reicht eine gewöhnliche Unterschrift nicht aus.',intro:'Schriftform, öffentliche Beglaubigung und notarielle Beurkundung erfüllen unterschiedliche Aufgaben. Die Textform ist eine zusätzliche, weniger strenge Form.',theory:[
  {title:'Schriftform',body:'Bei gesetzlicher **Schriftform** ist in der Regel eine **eigenhändige Namensunterschrift** erforderlich (§ 126 BGB). Beispiele: **Kündigung eines Arbeitsverhältnisses**, **Kündigung eines Wohnraummietvertrags**, private Bürgschaftserklärung (mit Ausnahmen).'},
  {title:'Öffentliche Beglaubigung',body:'Bei der **öffentlichen Beglaubigung** wird insbesondere die **Echtheit einer Unterschrift** amtlich/notariell bestätigt (§ 129 BGB). Beispiel: **Anmeldung zum Handels- oder Vereinsregister** (je nach Vorschrift).'},
  {title:'Notarielle Beurkundung',body:'Bei einer **notariellen Beurkundung** wird der **Inhalt** der Erklärung in einer notariellen Niederschrift aufgenommen und rechtlich betreut. Typische Beispiele: **Grundstückskaufvertrag**, **Ehevertrag**, **Schenkungsversprechen** (vor Leistung, mit Ausnahmen).'},
  {title:'Eigenhändiges Testament',body:'Ein privatschriftliches Testament muss grundsätzlich **vollständig eigenhändig geschrieben und unterschrieben** werden (§ 2247 BGB); nur ein ausgedruckter und unterschriebener Text reicht nicht.'}],takeaway:'Beglaubigung bestätigt vor allem die Unterschrift; Beurkundung umfasst den rechtlich betreuten Erklärungsinhalt.'},
 {id:'f3',chapter:'f',index:'09',title:'Formmängel richtig beurteilen',icon:'scale',diagram:'decision',story:'Mira prüft vier Vorgänge: einen Grundstückskauf per E-Mail, einen mündlichen Ausbildungsvertrag, einen langen Wohnraummietvertrag und eine versprochene Spende.',intro:'Nicht jeder Formfehler hat dieselbe Rechtsfolge. Für rechtssichere Falllösungen müssen Sie die jeweilige Sonderregel kennen.',theory:[
  {title:'Grundregel: Formnichtigkeit',body:'Fehlt die **gesetzlich vorgeschriebene Form**, ist das Rechtsgeschäft nach **§ 125 Satz 1 BGB** grundsätzlich **nichtig**. Allerdings können besondere Heilungs- oder Rechtsfolgeregeln eingreifen.'},
  {title:'Ausbildungsvertrag',body:'Ein **mündlich geschlossener Berufsausbildungsvertrag** ist nicht allein wegen der fehlenden schriftlichen Niederlegung unwirksam. Nach **§ 11 BBiG** muss der wesentliche Vertragsinhalt **in Textform** abgefasst werden – das ist eine Dokumentationspflicht der Ausbildenden.'},
  {title:'Wohnraummiete länger als ein Jahr',body:'Wird bei einem auf länger als ein Jahr angelegten **Wohnraummietvertrag** die **Schriftform** nicht eingehalten, gilt er nach **§ 550 BGB** grundsätzlich als **auf unbestimmte Zeit geschlossen** – nicht automatisch als nichtig. Weitere Regeln, beispielsweise zur Wohnraumbefristung, bleiben relevant.'},
  {title:'Schenkung und Mieterhöhung',body:'Ein zunächst formfehlerhaftes **Schenkungsversprechen** kann durch **Bewirkung der Leistung** wirksam werden (§ 518 Abs. 2 BGB). Eine **Modernisierungsmieterhöhung** muss nach **§ 559b BGB** in **Textform** erklärt und nachvollziehbar begründet werden; „schriftlich“ allein beweist noch keine Wirksamkeit.'}],takeaway:'Prüfen: Regel – Form – Einhaltung – Sonderfolge/Heilung – Ergebnis.'}
];
